//! The bridge between the interface and Anki's Rust core.
//!
//! The interface sends a protobuf-encoded request with the service and method
//! numbers the core dispatches on (generated by `codegen` from the core's own
//! descriptor set). The reply is one status byte followed by the encoded
//! response (status 0) or an encoded `anki.backend.BackendError` (status 1).
//! A panic inside the core is caught and comes back as an error.

use std::panic::catch_unwind;
use std::panic::AssertUnwindSafe;
use std::sync::RwLock;

use anki::backend::init_backend;
use anki::backend::Backend;
use anki_proto::backend::backend_error::Kind;
use anki_proto::backend::BackendError;
use anki_proto::backend::BackendInit;
use prost::Message;
use tauri::ipc::InvokeBody;
use tauri::ipc::Request;
use tauri::ipc::Response;
use tauri::State;

pub struct Core {
    backend: RwLock<Backend>,
    langs: RwLock<Vec<String>>,
}

pub const STATUS_OK: u8 = 0;
pub const STATUS_ERROR: u8 = 1;

impl Core {
    pub fn new(langs: Vec<String>) -> anyhow::Result<Self> {
        let backend = make_backend(&langs)?;
        Ok(Core {
            backend: RwLock::new(backend),
            langs: RwLock::new(langs),
        })
    }

    pub fn backend(&self) -> Backend {
        self.backend.read().unwrap().clone()
    }

    pub fn langs(&self) -> Vec<String> {
        self.langs.read().unwrap().clone()
    }

    /// Replaces the backend, for a new interface language or after a panic
    /// that may have poisoned the core's collection lock. The caller must
    /// close any open collection first and open it again afterwards.
    pub fn replace(&self, langs: Vec<String>) -> anyhow::Result<()> {
        let backend = make_backend(&langs)?;
        *self.backend.write().unwrap() = backend;
        *self.langs.write().unwrap() = langs;
        Ok(())
    }

}

/// Runs one core method, turning a panic into an encoded error.
fn run(backend: &Backend, service: u32, method: u32, input: &[u8]) -> (u8, Vec<u8>) {
    let result = catch_unwind(AssertUnwindSafe(|| {
        backend.run_service_method(service, method, input)
    }));
    match result {
        Ok(Ok(bytes)) => (STATUS_OK, bytes),
        Ok(Err(bytes)) => (STATUS_ERROR, bytes),
        Err(payload) => (
            STATUS_ERROR,
            encoded_error(Kind::AnkidroidPanicError, panic_message(&*payload)),
        ),
    }
}

fn make_backend(langs: &[String]) -> anyhow::Result<Backend> {
    let init = BackendInit {
        preferred_langs: langs.to_vec(),
        locale_folder_path: String::new(),
        server: false,
    }
    .encode_to_vec();
    match catch_unwind(|| init_backend(&init)) {
        Ok(Ok(backend)) => Ok(backend),
        Ok(Err(message)) => anyhow::bail!(message),
        Err(payload) => anyhow::bail!(panic_message(&*payload)),
    }
}

pub fn encoded_error(kind: Kind, message: String) -> Vec<u8> {
    BackendError {
        message,
        kind: kind as i32,
        ..Default::default()
    }
    .encode_to_vec()
}

pub(crate) fn panic_message(payload: &(dyn std::any::Any + Send)) -> String {
    let detail = if let Some(text) = payload.downcast_ref::<&str>() {
        (*text).to_string()
    } else if let Some(text) = payload.downcast_ref::<String>() {
        text.clone()
    } else {
        "unknown panic payload".to_string()
    };
    format!("The Anki core panicked: {detail}")
}

#[cfg(test)]
mod tests {
    use anki::services::BackendCollectionService;
    use anki_proto::collection::OpenCollectionRequest;
    use anki_proto::decks::DeckTreeNode;
    use anki_proto::decks::DeckTreeRequest;

    use super::*;

    #[test]
    fn opens_a_collection_and_runs_numbered_methods() {
        let dir = std::env::temp_dir().join(format!("hayaki-core-test-{}", std::process::id()));
        std::fs::create_dir_all(dir.join("media")).unwrap();
        let core = Core::new(vec!["en".into()]).unwrap();
        let backend = core.backend();
        backend
            .open_collection(OpenCollectionRequest {
                collection_path: dir.join("collection.anki2").to_string_lossy().into(),
                media_folder_path: dir.join("media").to_string_lossy().into(),
                media_db_path: dir.join("media.db2").to_string_lossy().into(),
            })
            .unwrap();
        // Through the numbered dispatch the interface uses (DecksService is
        // service 7, DeckTree method 4 in Anki 26.09.4).
        let input = DeckTreeRequest { now: 0 }.encode_to_vec();
        let (status, bytes) = run(&backend, 7, 4, &input);
        assert_eq!(status, STATUS_OK);
        let tree = DeckTreeNode::decode(bytes.as_slice()).unwrap();
        assert_eq!(tree.children.len(), 1, "a new collection has the Default Deck");

        // An invalid method comes back as an encoded error, not a panic.
        let (status, _) = run(&backend, 7, 9999, &[]);
        assert_eq!(status, STATUS_ERROR);

        backend
            .close_collection(anki_proto::collection::CloseCollectionRequest {
                downgrade_to_schema11: false,
            })
            .unwrap();
        let _ = std::fs::remove_dir_all(dir);
    }
}

fn header_u32(request: &Request<'_>, name: &str) -> Result<u32, String> {
    request
        .headers()
        .get(name)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse().ok())
        .ok_or_else(|| format!("missing header {name}"))
}

fn reply(status: u8, mut bytes: Vec<u8>) -> Response {
    bytes.insert(0, status);
    Response::new(bytes)
}

/// Runs one method of the core off the main thread. Calls that need the
/// collection queue on the core's own lock; progress and abort calls do not,
/// so they answer while a long operation runs.
#[tauri::command]
pub async fn core_call(request: Request<'_>, core: State<'_, Core>) -> Result<Response, String> {
    let service = header_u32(&request, "x-service")?;
    let method = header_u32(&request, "x-method")?;
    let input = match request.body() {
        InvokeBody::Raw(bytes) => bytes.clone(),
        InvokeBody::Json(serde_json::Value::Null) => Vec::new(),
        InvokeBody::Json(_) => return Err("core_call expects a binary body".into()),
    };
    let backend = core.backend();
    let (status, bytes) =
        tauri::async_runtime::spawn_blocking(move || run(&backend, service, method, &input))
            .await
    .map_err(|err| err.to_string())?;
    Ok(reply(status, bytes))
}
